import os, math, json, subprocess
from PIL import Image
from pathlib import Path
root=str(Path(__file__).resolve().parents[1])
os.makedirs(root+'/public/stickers',exist_ok=True)
os.makedirs(root+'/art/stickers',exist_ok=True)
ink='#715c4d';sage='#8a997b';rose='#b77d82';cream='#f4e9cf';gold='#c2a468'
items=[]
def make(id,name,group,body):
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="256" height="256" viewBox="0 0 200 200"><defs><pattern id="h" width="5" height="5" patternUnits="userSpaceOnUse"><path d="M0 5L5 0" stroke="#75644b" stroke-width=".5" opacity=".13"/></pattern></defs><g stroke="{ink}" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">{body}</g></svg>'''
 path=root+'/art/stickers/'+id+'.svg';open(path,'w').write(svg)
 subprocess.run(['convert','-background','none',path,root+'/public/stickers/'+id+'.png'],check=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
 im=Image.open(root+'/public/stickers/'+id+'.png');im.save(root+'/public/stickers/'+id+'.webp',lossless=True);os.unlink(root+'/public/stickers/'+id+'.png')
 items.append(dict(id=id,name=name,group=group))
def bow(c):return f'<path fill="{c}" d="M96 92C52 40 24 54 40 91Q53 115 92 103L61 157L85 147L98 166L105 109L124 163L139 144L160 154L114 102Q170 117 168 76C165 44 127 69 108 91Z"/><path fill="url(#h)" d="M96 92C52 40 24 54 40 91Q53 115 92 103L61 157L85 147L98 166L105 109L124 163L139 144L160 154L114 102Q170 117 168 76C165 44 127 69 108 91Z"/><rect x="92" y="86" width="20" height="24" rx="6" fill="{c}"/><path d="M49 72L88 94M126 94L156 76M98 117L81 146M114 114L136 145" fill="none" opacity=".65"/>'
make('rose-bow','Rose ribbon','Botanical',bow(rose));make('sage-bow','Sage ribbon','Botanical',bow(sage))
def flower(x,y,r,c):
 return ''.join(f'<ellipse cx="{x}" cy="{y-r*.6}" rx="{r*.45}" ry="{r*.7}" fill="{c}" transform="rotate({a} {x} {y})"/>' for a in range(0,360,60))+f'<circle cx="{x}" cy="{y}" r="{r*.25}" fill="{gold}"/>'
stem=f'<path d="M95 169Q115 107 96 63M102 133Q64 125 65 100Q97 100 102 133M104 113Q139 110 141 85Q113 88 104 113" fill="{sage}"/>'
make('pressed-rose','Pressed rose','Botanical',stem+flower(96,65,30,rose))
make('daisy','Garden daisy','Botanical',stem+flower(96,65,27,cream))
make('bouquet','Little bouquet','Botanical','<path d="M76 166L64 97L138 96L120 166Z" fill="#d4bc91"/>'+''.join(f'<path d="M100 162L{x} {y}"/>'+flower(x,y,18,c) for x,y,c in [(65,78,cream),(101,59,rose),(135,82,cream),(100,99,rose)])+'<path d="M77 145Q100 129 124 146" fill="none"/>')
make('olive','Olive branch','Botanical','<path d="M62 173Q124 100 139 34" fill="none"/>'+''.join(f'<ellipse cx="{x}" cy="{y}" rx="11" ry="24" transform="rotate({a} {x} {y})" fill="{sage}"/>' for x,y,a in [(76,139,-45),(106,137,45),(96,109,-45),(126,101,45),(113,76,-35),(140,65,35)]))
make('lavender','Lavender sprigs','Botanical',''.join(f'<path d="M98 174L{x} 57" fill="none"/>'+''.join(f'<ellipse cx="{x+(j%2*10-5)}" cy="{60+j*10}" rx="8" ry="10" fill="#a397b2"/>' for j in range(6)) for x in [76,101,125]))
make('butterfly','Sage butterfly','Botanical',f'<path d="M99 99C52 18 14 57 55 112C13 149 69 173 98 112C125 176 181 149 145 112C185 48 143 24 102 99Z" fill="{sage}"/><path d="M99 83L100 139M98 88Q77 62 83 61M102 88Q119 60 120 65M91 107L51 75M108 107L149 73M92 117L63 140M109 119L137 142" fill="none"/><path d="M48 71Q55 51 82 90M119 90Q150 47 155 68" stroke="{cream}" stroke-width="4" fill="none"/>')
make('books','Well-loved books','Cozy',f'<path d="M43 135L145 124L166 143L65 159Z" fill="{rose}"/><path d="M44 135V152L65 171L166 154V143L65 159Z" fill="{cream}"/><path d="M43 107L145 96L166 115L65 131Z" fill="{sage}"/><path d="M43 107V123L65 142L166 126V115L65 131Z" fill="{cream}"/><path d="M43 79L145 68L166 87L65 103Z" fill="#94775d"/><path d="M43 79V94L65 114L166 98V87L65 103Z" fill="{cream}"/><path d="M73 110L156 94M72 137L155 122M71 165L157 151M59 83L140 74" fill="none"/>')
make('teacup','Afternoon tea','Cozy',f'<ellipse cx="100" cy="151" rx="70" ry="13" fill="{cream}"/><path d="M138 86Q186 67 170 110Q162 129 139 121" fill="none" stroke-width="7"/><path d="M46 84Q50 151 99 151Q147 149 150 84Z" fill="{cream}"/><ellipse cx="98" cy="84" rx="52" ry="14" fill="#8d6952"/><path d="M69 62Q55 45 72 30M99 58Q115 44 101 26M125 62Q141 46 130 34" fill="none" stroke="{sage}"/>'+flower(98,119,15,rose))
make('candle','Evening candle','Cozy',f'<ellipse cx="100" cy="163" rx="48" ry="10" fill="{gold}"/><path d="M74 76H127V159Q102 174 74 159Z" fill="{cream}"/><path d="M75 80Q88 103 93 80Q101 117 108 80Q121 100 127 80" fill="none"/><path d="M100 76V61"/><path d="M100 61Q75 46 102 22Q126 47 100 61Z" fill="{gold}"/><path d="M89 141L114 141M90 147L112 147"/>')
make('envelope','Sealed letter','Cozy',f'<path d="M34 62L164 49L176 139L45 154Z" fill="{cream}"/><path d="M34 62L106 110L164 49M45 154L91 103M176 139L118 102" fill="none"/><circle cx="106" cy="111" r="15" fill="{rose}"/><path d="M98 111L104 119L115 102" fill="none"/>')
make('key','Keepsake key','Cozy',f'<circle cx="79" cy="67" r="28" fill="{gold}"/><circle cx="79" cy="67" r="15" fill="{cream}"/><path d="M94 86L155 148L148 155L136 143L126 151L115 138L125 130L85 94Z" fill="{gold}"/>')
make('cat','Sleepy cat','Cozy',f'<path d="M48 111Q20 155 79 163H132Q177 157 158 126Q151 111 129 121L119 90L102 106L78 103L61 87L58 115Z" fill="#a39b83"/><path d="M40 145Q19 108 55 99M83 128Q90 137 97 128M113 129Q120 138 127 129M105 139L109 142L113 138M127 152Q161 125 159 148" fill="none"/><path d="M64 119L49 113M65 126L46 125M130 121L145 114M132 129L150 127"/>')
make('camera','Old camera','Cozy',f'<rect x="31" y="72" width="138" height="91" rx="12" fill="#91836e"/><path d="M50 72V56H84L91 72" fill="{cream}"/><rect x="40" y="82" width="120" height="17" fill="{cream}"/><circle cx="105" cy="122" r="32" fill="#715c4d"/><circle cx="105" cy="122" r="24" fill="#a8b2a0"/><circle cx="105" cy="122" r="15" fill="#5b635d"/><circle cx="98" cy="114" r="5" fill="{cream}"/><rect x="139" y="105" width="15" height="12" fill="{gold}"/>')
make('frame','Memory frame','Cozy',f'<rect x="48" y="29" width="105" height="147" rx="40" fill="{gold}"/><rect x="58" y="39" width="85" height="127" rx="33" fill="{cream}"/><rect x="65" y="46" width="71" height="113" rx="28" fill="{sage}"/><path d="M73 149L126 61M79 151L133 60" opacity=".35" stroke="{cream}" stroke-width="4"/>'+''.join(f'<circle cx="{x}" cy="{y}" r="3" fill="{cream}"/>' for x,y in [(51,75),(51,130),(150,75),(150,130),(100,33),(100,172)]))
make('moon','Golden crescent','Celestial',f'<path d="M132 29A73 73 0 1 0 161 144A68 68 0 0 1 132 29Z" fill="{gold}"/><path d="M80 49Q33 106 87 155M73 68L65 82M67 126L79 142" fill="none" opacity=".5"/>')
def star(x,y,r,c):return f'<path d="M{x} {y-r}L{x+r*.27} {y-r*.27}L{x+r} {y}L{x+r*.27} {y+r*.27}L{x} {y+r}L{x-r*.27} {y+r*.27}L{x-r} {y}L{x-r*.27} {y-r*.27}Z" fill="{c}"/>'
make('starlight','Scattered starlight','Celestial',star(85,101,43,gold)+star(142,59,20,gold)+star(142,147,17,gold)+star(44,51,10,gold))
make('sun','Little sun','Celestial',f'<circle cx="100" cy="100" r="34" fill="{gold}"/>'+''.join(f'<path d="M100 52L96 28L104 28Z" fill="{gold}" transform="rotate({a} 100 100)"/>' for a in range(0,360,30))+'<path d="M84 97Q89 91 94 97M108 97Q113 91 118 97M91 113Q101 122 112 111" fill="none"/>')
make('constellation','Little constellation','Celestial','<path d="M45 66L91 46L130 91L154 147L93 133L45 66" fill="none" stroke-dasharray="3 5"/>'+''.join(star(x,y,r,gold) for x,y,r in [(45,66,12),(91,46,8),(130,91,13),(154,147,10),(93,133,9)]))
def heart(c):return f'<path d="M100 163C-12 95 47 22 100 72C151 19 213 97 100 163Z" fill="{c}"/><path d="M100 163C-12 95 47 22 100 72C151 19 213 97 100 163Z" fill="url(#h)"/><path d="M57 74Q43 86 51 103" stroke="{cream}" stroke-width="5" fill="none"/>'
make('rose-heart','Rose heart','Love',heart(rose));make('sage-heart','Sage heart','Love',heart(sage))
make('love-stamp','Love postage','Love',f'<rect x="47" y="29" width="106" height="147" fill="{cream}" stroke-dasharray="3 5" stroke-width="8"/><rect x="58" y="40" width="84" height="125" fill="none"/>'+'<g transform="translate(50 40) scale(.5)">'+heart(rose)+'</g><path d="M70 133H130M79 142H121M85 151H115"/>')
make('heart-lock','Heart keepsake','Love',f'<path d="M71 94V64A29 29 0 0 1 129 64V94" fill="none" stroke="{gold}" stroke-width="12"/><g transform="translate(22 45) scale(.78)">'+heart(gold)+'</g><circle cx="100" cy="126" r="7" fill="#715c4d"/><path d="M100 132V145" stroke-width="5"/>')
open(root+'/src/sticker-pack.json','w').write(json.dumps(items,indent=2)+'\n')
open(root+'/art/stickers/README.md','w').write('# Dear Diary starter stickers\n\n24 original vector illustrations made for Dear Diary. No Pinterest artwork, external clip art, fonts, logos or other third-party image assets were used. The screenshots supplied by the user were mood references only.\n\nSource: the SVG files in this directory. App assets: lossless transparent 256px WebP files in public/stickers.\n\nThese original illustrations are dedicated to the public domain under CC0 1.0: https://creativecommons.org/publicdomain/zero/1.0/ . No attribution required.\n')
print('Created',len(items),'original stickers;',sum(os.path.getsize(root+'/public/stickers/'+x['id']+'.webp') for x in items),'bytes total')
